using ProjetoIntegradorBack.Domain.Entities; using ProjetoIntegradorBack.Domain.Interfaces; using ProjetoIntegradorBack.Infrastructure.Context; using ProjetoIntegradorBack.Shared.Pattern; using Microsoft.EntityFrameworkCore;
namespace ProjetoIntegradorBack.Infrastructure.Repositories;
public class ServiceRepository(ProjetoIntegradorBackDbContext context):IServiceRepository{
public async Task<Result<Service>> GetPorIdAsync(Guid id,CancellationToken ct=default){try{var e=await context.Services.FindAsync(new object[]{id},ct);return e==null?Result<Service>.AsFailure(new Failure(404,"Serviço não encontrado.")):Result<Service>.AsSuccess(e);}catch(Exception ex){return Result<Service>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<IReadOnlyList<Service>>> ListPorEstablishmentAsync(Guid id,CancellationToken ct=default){try{return Result<IReadOnlyList<Service>>.AsSuccess(await context.Services.Where(x=>x.EstablishmentId==id&&x.IsActive).ToListAsync(ct));}catch(Exception ex){return Result<IReadOnlyList<Service>>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<Service>> AddAsync(Service e,CancellationToken ct=default){try{e.Id=Guid.NewGuid();await context.Services.AddAsync(e,ct);await context.SaveChangesAsync(ct);return Result<Service>.AsSuccess(e);}catch(Exception ex){return Result<Service>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<Service>> UpdateAsync(Service e,CancellationToken ct=default){try{context.Services.Update(e);await context.SaveChangesAsync(ct);return Result<Service>.AsSuccess(e);}catch(Exception ex){return Result<Service>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<string>> DesativarAsync(Guid id,CancellationToken ct=default){try{var e=await context.Services.FindAsync(new object[]{id},ct);if(e==null)return Result<string>.AsFailure(new Failure(404,"Serviço não encontrado."));e.IsActive=false;await context.SaveChangesAsync(ct);return Result<string>.AsSuccess("Serviço desativado com sucesso.");}catch(Exception ex){return Result<string>.AsFailure(new Failure(500,ex.Message));}}}